import{_ as a,o as t,c as o,ao as n}from"./chunks/framework.DbC_DlpH.js";const h=JSON.parse('{"title":"PureAtomistic.jl","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),s={name:"index.md"};function i(r,e,c,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="PureAtomistic.jl" tabindex="-1">PureAtomistic.jl <a class="header-anchor" href="#PureAtomistic.jl" aria-label="Permalink to &quot;PureAtomistic.jl {#PureAtomistic.jl}&quot;">​</a></h1><p>Molecular dynamics on top of PureMLIP potentials, in pure Julia.</p><p>The package is organized in layers: <code>Systems</code> holds the atomic configuration, <code>Potentials</code> evaluates energies and forces, <code>Integrators</code>, <code>Thermostats</code> and <code>Barostats</code> advance it, <code>Analysis</code> reads the results, and <code>IO</code> reads and writes configurations.</p><p>The <a href="./gallery">example gallery</a> shows the validation runs of the molecular-dynamics driver: energy conservation, canonical sampling with the Bussi thermostat, and a vacancy at 1300 K.</p><p><a href="./analysis">Trajectory analysis</a> covers <code>g(r)</code>, coordination numbers, the mean-square displacement and diffusion coefficient, and RMSD, with the atomic diffusion of a vacancy at 1200 K as an example.</p><h2 id="Molecular-dynamics-on-a-GPU" tabindex="-1">Molecular dynamics on a GPU <a class="header-anchor" href="#Molecular-dynamics-on-a-GPU" aria-label="Permalink to &quot;Molecular dynamics on a GPU {#Molecular-dynamics-on-a-GPU}&quot;">​</a></h2><p>With KernelAbstractions and a vendor package loaded, the velocity Verlet step, the Bussi and Langevin thermostats and the Berendsen barostat run on the device; see <a href="./gpu">GPU</a>.</p>',7)])])}const p=a(s,[["render",i]]);export{h as __pageData,p as default};
